enum class CompressionLevel {
    Fastest = 1,
    Standard = 3,
    Nice = 5,
    BestSpeed = 7,
    Huge = 10
};

using DictType = std::vector<unsigned char>;

inline int CompressData(const unsigned char* srcPtr, size_t srcSz, unsigned char* dstPtr, size_t& dstCapacity, size_t desiredMaxCompSize, CompressionLevel level = CompressionLevel::Standard) {
    assert(srcPtr && dstPtr);

    dictmem memCtx{};
    memCtx.initParams.memoryLimit = desiredMaxCompSize + kDefaultReserveBytes;
    memCtx.initParams.dictMemory = nullptr;
    memCtx.initParams.dictMemSize = 0;
    memCtx.initParams.parallelism = 1;
    memCtx.initParams.verboseMode = false;

    ZZ dictHandle{};
    if (!zz_DictCreateFromString(memCtx, reinterpret_as_const_byte_(kTestDictionary))) {
        throw runtime_error("Failed creating dictionary");
    }

    memCtx.setDictionary(dictHandle);

    ZZ compressor{};
    if (!zz_create(&compressor, memCtx, level)) {
        throw runtime_error("Could not initialize compressor");
    }

    size_t compressedSize = 0;
    if (!zz_compressToBuffer(compressor, dstPtr, dstCapacity, reinterpret_as_const_byte_(srcPtr), srcSz, &compressedSize)) {
        throw runtime_error("Error during compression process");
    }

    dstCapacity = compressedSize;
    return static_cast<int>(compressedSize > 0);
}

