private:
    mutex m_;
    condition_variable cv_;
    atomic<bool>& initialized_;
    atomic<int>& errorCode_;

    void initialize() {
        lock_guard<mutex>() guard(m_);
        if (!initialized_) {
            dictmem memCtx{};
            memCtx.initParams.memoryLimit = MB(8);  // 8MB buffer
            memCtx.initParams.dictMemory = nullptr;
            memCtx.initParams.dictMemSize = 0;
