int Zlib::NormalUncompress(uint8_t* dest, uint32_t* destLen, const uint8_t* source, uint32_t sourceLen) {
    if (sourceLen == 0 || !(*destLen >= sourceLen)) {
        return -1;
    }

    auto resultSize = DecompressData(dest, (*destLen), source, sourceLen);
    if (resultSize == 0) {
        return -1;
    }

    (*destLen) = static_cast<uint32_t>(resultSize);
